const filteredFiles = items
  .filter(item => {
    const name = item.json.name;
    return name.endsWith('.docx') || name.endsWith('.pdf');
  })
  .map(item => item.json);

return filteredFiles.map(file => ({ json: file }));

// Initialize token counts
let promptTokens = 0;
let completionTokens = 0;
let totalTokens = 0;
let latency = 0;

// Safely access the input JSON data
const data = $node["AI Agent"].json;

// Path to the token metadata in the JSON structure
const usagePath = data?.intermediateSteps?.[0]?.action?.messageLog?.[0]?.kwargs?.usage_metadata;

// If the metadata exists, extract the token values
if (usagePath) {
    promptTokens = usagePath.input_tokens || 0;
    completionTokens = usagePath.output_tokens || 0;
    totalTokens = usagePath.total_tokens || 0;
}

// Optionally extract latency if available
if (data.latency) {
    latency = data.latency;
}

// Return the token counts and latency
return {
    promptTokens,
    completionTokens,
    totalTokens,
    latency:   $input.first().json.latency
};

// End Node (JavaScript code)
const endTime = Date.now();

// Fetch the start time from the previous node named "Set Start Time"
const startTime =$('startTime').first().json.startTime;

// Calculate the latency in milliseconds
const latencyMs = endTime - startTime;

// Return the latency value
return {
    latency: latencyMs + " ms"
};
